    "summaryZh": "2026-08-22 百度热搜第 7 名，热度 733.4万。8月18日，江苏盐城大丰区警方接到小王报警，称被困汽车后备箱无法脱身。此前小王取物品时误碰电动按钮致后备箱关闭反锁，车钥匙手机均在前排够不到，近40℃高温下被困5小时。危急时他借助手机语音助手拨打110。民警沿途鸣警笛，凭听筒中警笛声强弱锁定车辆位置，联系119消防切割车体，经1个多小时将其救出。",
